# Blood and Tears zone maps. Our own outlines: points placed by hand against a grid laid over the
# game's world map, so zones sit where they do in game. No map art is copied or traced automatically.
W=500
def ell(cx,cy,rx,ry,n=10):
    import math
    return [(round(cx+rx*math.cos(2*math.pi*i/n),1),round(cy+ry*math.sin(2*math.pi*i/n),1)) for i in range(n)]
